	/**
	 * Inside a transaction carrying uncommitted writes the leapfrog rung currently declines entirely (opened delta 0)
	 * and the adjacency view is additionally fenced off ({@code view.isExact()} / pinned-txn-version guard), so no
	 * adjacency state — stale or fresh — can serve a dirty-transaction query. This pins the safety half of that
	 * contract: results reflect the uncommitted removal exactly and key enumeration never engages.
	 */
	@Test
	public void uncommittedRemovalsFallBackToScannedFrontiers() throws Exception {
		previousNative = System.getProperty(NATIVE_FLAG);
		previousDirectFrontiers = System.getProperty("rdf4j.lmdb.wcoj.directFrontiers.enabled");

		openRepositoryWithTriangles();
		store.getBackingStore().directAdjacencyStore().buildNowForTest();

		System.setProperty(NATIVE_FLAG, "true");
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI knows = vf.createIRI(EX, "knows");
			conn.begin();
			// Remove every edge leaving d: the d-e-f triangle must disappear and d must leave the key domain.
			conn.remove(vf.createIRI(EX, "d"), knows, vf.createIRI(EX, "e"));

			System.clearProperty("rdf4j.lmdb.wcoj.directFrontiers.enabled");
			List<String> expected = rowsOn(conn, TRIANGLE);

			System.setProperty("rdf4j.lmdb.wcoj.directFrontiers.enabled", "true");
			long enumeratedBefore = JoinDispatchTestAccess.leapfrogEnumeratedFrontiers();
			List<String> actual = rowsOn(conn, TRIANGLE);

			assertThat(expected).as("the a-b-c triangle must survive the in-transaction removal")
					.anyMatch(rowText -> rowText.contains(EX + "a"));
			assertThat(expected).as("the d-e-f triangle must be gone after the in-transaction removal")
					.noneMatch(rowText -> rowText.contains(EX + "d"));
			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
			assertThat(JoinDispatchTestAccess.leapfrogEnumeratedFrontiers())
					.as("no adjacency key enumeration may serve a dirty-transaction query")
					.isEqualTo(enumeratedBefore);
			conn.rollback();
		}
	}

